INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','articles','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"articles","title":"Articles: a, an and the","level":"A1","order":6,"summary":"Choose an indefinite, definite or zero article using sound and context.","learningGoals":["One nonspecific item","An identified item","General plural nouns"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"One nonspecific item","explanation":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","examples":["a uniform","an hourglass"]},{"title":"An identified item","explanation":"Use the when the listener can identify the item, including a second mention. The also works with identified plural nouns.","examples":["I found a ring. The ring was silver.","Please return the borrowed books."]},{"title":"General plural nouns","explanation":"Usually omit the article before a plural noun when referring to its whole class. In these exercises, — means no article.","examples":["Bicycles need regular maintenance.","The bicycles outside are ours."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-articles","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"18e96eb9-fdb3-59e3-aea9-9fa47b04a541","topicSlug":"articles","level":"A1","prompt":"First mention, no particular item: I would like ____ apple.","choices":[{"id":"A","text":"an"},{"id":"B","text":"a"},{"id":"C","text":"the"},{"id":"D","text":"—"}],"answerId":"A","hint":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound. Focus on **indefinite sound** in this question.","explanation":"Use an for one nonspecific apple. The first sound of “apple” is a vowel sound.","keywords":[],"source":"seed","skill":"indefinite-sound","contextKey":"noun-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-articles","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"fd8ed28a664190ef1b2641baf345d707f8f12dad4039afd9b4ba842ddaa4f211","teaching":{"steps":["Identify what the question tests: **indefinite sound**. Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","Use an for one nonspecific apple. The first sound of “apple” is a vowel sound.","Choose **an**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"Use an for one nonspecific apple. The first sound of “apple” is a vowel sound.","B":"**a** is chosen for a consonant sound, but the next word begins with a vowel sound. Choose by pronunciation, not just spelling.","C":"The would identify a particular item, but the prompt explicitly introduces one nonspecific item.","D":"A singular countable noun needs a determiner here; leaving the article out does not form the requested phrase."}}},{"id":"d11d2e07-d457-504d-a340-0781dd81700c","topicSlug":"articles","level":"A1","prompt":"I found an apple. ____ apple I found belongs to my neighbour.","choices":[{"id":"A","text":"—"},{"id":"B","text":"The"},{"id":"C","text":"A"},{"id":"D","text":"An"}],"answerId":"B","hint":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound. Focus on **second mention** in this question.","explanation":"The second mention identifies the same apple, so use the.","keywords":[],"source":"seed","skill":"second-mention","contextKey":"noun-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-articles","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"65e74b1f7f62478fec169f0d241a41666c97b4a4cd5400796881b8bf3ff92568","teaching":{"steps":["Identify what the question tests: **second mention**. Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","The second mention identifies the same apple, so use the.","Choose **The**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"No article would leave a general or incomplete reference; this question explicitly identifies a particular item or set.","B":"The second mention identifies the same apple, so use the.","C":"**A** would introduce another nonspecific item; this mention identifies the same item already introduced.","D":"**An** would introduce another nonspecific item; this mention identifies the same item already introduced."}}},{"id":"f8a2c058-831a-5134-ad9b-cba795a895fb","topicSlug":"articles","level":"A1","prompt":"Talk about the whole category, not particular items: ____ apples come in many varieties.","choices":[{"id":"A","text":"—"},{"id":"B","text":"a"},{"id":"C","text":"an"},{"id":"D","text":"the"}],"answerId":"A","hint":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound. Focus on **general plural** in this question.","explanation":"For apples in general, use the plural noun without an article. — means no article.","keywords":[],"source":"seed","skill":"general-plural","contextKey":"noun-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-articles","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"7f2db88070e5aaedd9a195393a295da73ef3c3588bd3b1d5d2ba4ac3da7c6568","teaching":{"steps":["Identify what the question tests: **general plural**. Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","For apples in general, use the plural noun without an article. — means no article.","Choose **—**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"For apples in general, use the plural noun without an article. — means no article.","B":"**a** is singular, but the noun in this question is plural.","C":"**an** is singular, but the noun in this question is plural.","D":"The would narrow the reference to an identifiable set, but the prompt asks about the whole category."}}},{"id":"9b61e4ec-39a0-5f3e-ab4b-8684c1e36de5","topicSlug":"articles","level":"A1","prompt":"We are discussing a particular set: please count ____ apples in this photograph.","choices":[{"id":"A","text":"a"},{"id":"B","text":"an"},{"id":"C","text":"—"},{"id":"D","text":"the"}],"answerId":"D","hint":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound. Focus on **identified plural** in this question.","explanation":"The phrase “in this photograph” identifies a specific set of apples; use the.","keywords":[],"source":"seed","skill":"identified-plural","contextKey":"noun-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-articles","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"b99408bdf70ccebf493c8b5d6c4c5e71407e7758dbf021ad66b11f399d9f9312","teaching":{"steps":["Identify what the question tests: **identified plural**. Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","The phrase “in this photograph” identifies a specific set of apples; use the.","Choose **the**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**a** is singular, but the noun in this question is plural.","B":"**an** is singular, but the noun in this question is plural.","C":"No article would leave a general or incomplete reference; this question explicitly identifies a particular item or set.","D":"The phrase “in this photograph” identifies a specific set of apples; use the."}}},{"id":"500d6065-7a18-5eca-a287-cf7008b0160c","topicSlug":"articles","level":"A1","prompt":"First mention, no particular item: I would like ____ banana.","choices":[{"id":"A","text":"a"},{"id":"B","text":"an"},{"id":"C","text":"the"},{"id":"D","text":"—"}],"answerId":"A","hint":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound. Focus on **indefinite sound** in this question.","explanation":"Use a for one nonspecific banana. The first sound of “banana” is a consonant sound.","keywords":[],"source":"seed","skill":"indefinite-sound","contextKey":"noun-banana","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-articles","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"a41b610190cce47a764c0c638c59d9b187fe2e352857d558aff6e31711d8aed4","teaching":{"steps":["Identify what the question tests: **indefinite sound**. Use a or an before a singula